    function makeSvgIcon(label, bgHex, accentHex, shape) {
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300" viewBox="0 0 400 300">
        <rect width="400" height="300" fill="${bgHex}"/>
        <circle cx="200" cy="140" r="88" fill="${accentHex}" opacity="0.14"/>
        ${shape}
        <text x="200" y="268" text-anchor="middle" font-family="Inter, sans-serif" font-size="16" font-weight="800" fill="#991b1b">${label}</text>
      </svg>`;
      return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    }

