    // --- STORAGE HELPERS ---
    function loadState() {
      try {
        const savedProds = localStorage.getItem('srinivasa_products_v1');
        const savedOffers = localStorage.getItem('srinivasa_offers_v1');
        const savedConf = localStorage.getItem('srinivasa_config_v1');
        const savedCart = localStorage.getItem('srinivasa_cart_v1');
        products = savedProds ? JSON.parse(savedProds) : [...DEFAULT_PRODUCTS];
        offers = savedOffers ? JSON.parse(savedOffers) : [...DEFAULT_OFFERS];
        config = savedConf ? { ...DEFAULT_CONFIG, ...JSON.parse(savedConf) } : { ...DEFAULT_CONFIG };
        cart = savedCart ? JSON.parse(savedCart) : [];
      } catch (e) {
        products = [...DEFAULT_PRODUCTS];
        offers = [...DEFAULT_OFFERS];
        config = { ...DEFAULT_CONFIG };
        cart = [];
      }
    }

    function saveOffers() {
      try { localStorage.setItem('srinivasa_offers_v1', JSON.stringify(offers)); } catch (e) {}
    }
    function saveProducts() {
      try { localStorage.setItem('srinivasa_products_v1', JSON.stringify(products)); } catch (e) {}
    }
    function saveConfig() {
      try { localStorage.setItem('srinivasa_config_v1', JSON.stringify(config)); } catch (e) {}
    }
    function saveCart() {
      try { localStorage.setItem('srinivasa_cart_v1', JSON.stringify(cart)); } catch (e) {}
    }

    // --- TOAST ---
    let toastTimer = null;
    function showToast(msg) {
      const el = document.getElementById('toast');
      document.getElementById('toast-msg').textContent = msg;
      el.classList.remove('hidden');
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => el.classList.add('hidden'), 2600);
    }

    // --- APPLY DEVELOPER CONFIG LIVE ---
      function renderDevContactLists() {
        const pEl = document.getElementById('dev-phones-list');
        if (pEl) {
          pEl.innerHTML = (config.phones || []).map((ph, i) => `
            <div class="flex items-center justify-between bg-gray-800 px-2 py-1 rounded">
              <span class="truncate">${ph}</span>
              <button type="button" data-del-phone="${i}" class="text-red-400 hover:text-red-300 font-bold ml-2">&times;</button>
            </div>
          `).join('');
        }
        const wEl = document.getElementById('dev-wa-list');
        if (wEl) {
          wEl.innerHTML = (config.whatsapps || []).map((w, i) => `
            <div class="flex items-center justify-between bg-gray-800 px-2 py-1 rounded">
              <span class="truncate">${w}</span>
              <button type="button" data-del-wa="${i}" class="text-red-400 hover:text-red-300 font-bold ml-2">&times;</button>
            </div>
          `).join('');
        }
        const sEl = document.getElementById('dev-socials-list');
        if (sEl) {
          sEl.innerHTML = (config.socials || []).map((soc, i) => `
            <div class="flex items-center justify-between bg-gray-800 px-2 py-1 rounded">
              <span class="truncate">${soc.icon || '🔗'} ${soc.name}</span>
              <button type="button" data-del-social="${i}" class="text-red-400 hover:text-red-300 font-bold ml-2">&times;</button>
            </div>
          `).join('');
        }
      }

    function applyConfigToDOM() {
      const root = document.documentElement;
      root.style.setProperty('--primary', config.primaryColor);
      root.style.setProperty('--primary-bright', config.brightColor);
      root.style.setProperty('--primary-dark', config.darkColor);
      root.style.setProperty('--font-main', config.fontFamily);
      root.style.setProperty('--radius', config.radius + 'px');

      document.getElementById('header-shop-name').textContent = config.shopName;
      document.getElementById('splash-title-text').textContent = config.shopName;
      document.getElementById('footer-shop-name').textContent = config.shopName;
      document.getElementById('footer-copy-name').textContent = config.shopName;
      document.getElementById('hero-title-display').textContent = config.heroTitle;

      const primaryPhone = (config.phones && config.phones.length ? config.phones[0] : config.phone) || '+91 98480 21621';
      const cleanPhone = primaryPhone.replace(/[^+\d]/g, '');
      document.getElementById('hero-call-link').href = 'tel:' + cleanPhone;
      document.getElementById('footer-call-cta').href = 'tel:' + cleanPhone;
      document.getElementById('footer-phone-btn-text').textContent = primaryPhone;
      document.getElementById('footer-address-text').textContent = config.address;
      document.getElementById('footer-email-link').href = 'mailto:' + config.email;
      document.getElementById('footer-email-link').textContent = config.email;

      // Render all phone numbers
      const phonesList = config.phones && config.phones.length ? config.phones : [primaryPhone];
      document.getElementById('footer-phones-container').innerHTML = phonesList.map(ph => {
        const c = ph.replace(/[^+\d]/g, '');
        return `<a href="tel:${c}" class="font-bold hover:text-yellow-300 underline">${ph}</a>`;
      }).join('');

      // Render WhatsApp + Social Links in footer
      const waList = (config.whatsapps && config.whatsapps.length ? config.whatsapps : [primaryPhone]).map(w => {
        const digits = w.replace(/[^\d]/g, '');
        return `<a href="https://wa.me/${digits}" target="_blank" rel="noopener noreferrer" class="flex items-center gap-3 px-4 py-2.5 rounded-xl bg-green-600 hover:bg-green-500 text-white font-bold text-sm transition"><span>💬</span> WhatsApp (${w})</a>`;
      }).join('');
      const socList = (config.socials || []).map(soc => `
        <a href="${soc.url}" target="_blank" rel="noopener noreferrer" class="flex items-center gap-3 px-4 py-2.5 rounded-xl bg-white/15 hover:bg-white/25 text-white font-bold text-sm transition">
          <span>${soc.icon || '🔗'}</span> ${soc.name}
        </a>
      `).join('');
      document.getElementById('footer-socials-container').innerHTML = waList + socList;

      // Render Dev lists
      renderDevContactLists();

      const logoBox = document.getElementById('header-logo-box');
      const splashLogoBox = document.getElementById('splash-logo-box');
      const lSize = config.logoSize || 40;
      logoBox.style.width = lSize + 'px';
      logoBox.style.height = lSize + 'px';
      if (splashLogoBox) {
        const sSize = Math.round(lSize * 2.5);
        splashLogoBox.style.width = sSize + 'px';
        splashLogoBox.style.height = sSize + 'px';
      }
      if (config.logoDataUrl) {
        logoBox.innerHTML = `<img src="${config.logoDataUrl}" alt="Logo" class="w-full h-full object-cover" />`;
        if (splashLogoBox) splashLogoBox.innerHTML = `<img src="${config.logoDataUrl}" alt="Store Logo" class="w-full h-full object-contain rounded-full" />`;
      } else {
        logoBox.innerHTML = `<svg class="w-6 h-6" fill="none" stroke="currentColor" stroke-width="2.2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>`;
        if (splashLogoBox) splashLogoBox.innerHTML = `<svg class="w-16 h-16 text-red-600" fill="none" stroke="currentColor" stroke-width="2.2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>`;
      }

      const elCss = Object.entries(config.elementStyles || {}).map(([sel, st]) => {
        const rules = [];
        if (st.fontSize) rules.push(`font-size: ${st.fontSize}px !important`);
        if (st.color) rules.push(`color: ${st.color} !important`);
        if (st.bg) rules.push(`background-color: ${st.bg} !important`);
        if (st.fontFamily) rules.push(`font-family: ${st.fontFamily} !important`);
        return rules.length ? `${sel} { ${rules.join('; ')}; }` : '';
      }).join('\n');
      document.getElementById('dev-custom-css').textContent = elCss + '\n' + (config.customCss || '');

      // Sync Dev Inputs
      document.getElementById('dev-primary-color').value = config.primaryColor;
      document.getElementById('dev-bright-color').value = config.brightColor;
      document.getElementById('dev-font-select').value = config.fontFamily;
      document.getElementById('dev-radius-range').value = config.radius;
      document.getElementById('dev-radius-val').textContent = config.radius + 'px';
      document.getElementById('dev-logo-size-range').value = config.logoSize || 40;
      document.getElementById('dev-logo-size-val').textContent = (config.logoSize || 40) + 'px';
      document.getElementById('dev-shop-name').value = config.shopName;
      document.getElementById('dev-hero-title').value = config.heroTitle;
      document.getElementById('dev-email').value = config.email;
      document.getElementById('dev-address').value = config.address;
      document.getElementById('dev-owner-code').value = config.ownerCode;
      document.getElementById('dev-dev-code').value = config.devCode;
      document.getElementById('dev-css-input').value = config.customCss || '';
    }

    // --- SWIPEABLE FESTIVE OFFERS & EVENTS CAROUSEL (BELOW HEADER) ---
    function updateOfferSlidePosition() {
      const wrapper = document.getElementById('offer-slides-wrapper');
      if (!wrapper || offers.length === 0) return;
      if (currentOfferIndex >= offers.length) currentOfferIndex = 0;
      if (currentOfferIndex < 0) currentOfferIndex = offers.length - 1;
      wrapper.style.transform = `translateX(-${currentOfferIndex * 100}%)`;
      document.querySelectorAll('.offer-dot').forEach((d, idx) => {
        d.className = `offer-dot h-2 rounded-full transition-all ${idx === currentOfferIndex ? 'w-6 bg-yellow-400' : 'w-2 bg-white/40 hover:bg-white/70'}`;
      });
    }

    function renderFestiveOffers() {
      const wrapper = document.getElementById('offer-slides-wrapper');
      const dots = document.getElementById('offer-dots');
      if (!wrapper || !dots) return;
      if (!offers || offers.length === 0) {
        wrapper.innerHTML = `<div class="w-full shrink-0 p-4 text-center text-sm text-red-100">No active offers right now. Check back soon!</div>`;
        dots.innerHTML = '';
        return;
      }
      wrapper.innerHTML = offers.map(o => `
        <div data-offer-click="${o.id}" class="w-full shrink-0 rounded-xl bg-gradient-to-br from-red-600/90 to-red-900/95 border border-white/20 p-4 flex flex-col justify-between gap-3 hover:border-yellow-300 transition">
          ${o.image ? `<div class="w-full bg-white/95 rounded-lg p-1.5 flex items-center justify-center overflow-hidden border border-white/30 shadow-inner"><img src="${o.image}" alt="${o.title}" class="w-full max-h-56 object-contain rounded" /></div>` : ''}
          <div>
            <div class="flex items-center justify-between gap-2 mb-1.5">
              <span class="px-2.5 py-0.5 rounded-full bg-white/20 text-[10px] font-extrabold uppercase tracking-wider">${o.type}</span>
              <span class="px-2.5 py-0.5 rounded-full bg-yellow-400 text-red-950 text-[11px] font-black">${o.badge}</span>
            </div>
            <h3 class="text-lg sm:text-xl font-black leading-snug text-white">${o.title}</h3>
            <p class="text-xs text-red-100 mt-1 leading-relaxed">${o.desc}</p>
          </div>
          <div class="pt-2 border-t border-white/15 flex items-center justify-between text-xs font-bold text-yellow-300">
            <span>📅 ${o.date || 'Active Now'}</span>
            <span class="px-3 py-1 rounded-full bg-white text-red-700 font-extrabold text-[11px] shadow">View Event Items &rarr;</span>
          </div>
        </div>
      `).join('');

      dots.innerHTML = offers.map((_, idx) => `<button type="button" data-offer-dot="${idx}" aria-label="Slide ${idx + 1}" class="offer-dot h-2 w-2 rounded-full bg-white/40"></button>`).join('');
      updateOfferSlidePosition();
    }

    function renderOfferProductPicker(selectedIds = []) {
      const picker = document.getElementById('offer-products-picker');
      if (!picker) return;
      picker.innerHTML = products.map(p => `
        <label class="flex items-center gap-2 p-1 rounded hover:bg-red-100/60 cursor-pointer">
          <input type="checkbox" value="${p.id}" class="offer-prod-checkbox accent-red-600" ${selectedIds.includes(p.id) ? 'checked' : ''} />
          <span class="font-bold text-gray-800 truncate flex-1">${p.name}</span>
          <span class="text-[10px] text-red-700 font-extrabold shrink-0">₹${getFinalPrice(p)}</span>
        </label>
      `).join('');
    }

    function renderOwnerOffers() {
      const countEl = document.getElementById('owner-offers-count');
      const listEl = document.getElementById('owner-offers-list');
      if (!countEl || !listEl) return;
      countEl.textContent = offers.length;
      if (offers.length === 0) {
        listEl.innerHTML = '<p class="text-xs text-gray-500 py-4 text-center">No active offers or events. Publish one on the left!</p>';
        return;
      }
      listEl.innerHTML = offers.map(o => {
        const prodCount = o.productIds && o.productIds.length ? `${o.productIds.length} selected products` : (o.targetCategory || 'Category match');
        return `
        <div class="flex items-center justify-between gap-2 p-3 rounded-xl border border-red-100 bg-red-50/40">
          <div class="min-w-0 flex-1">
            <div class="flex items-center gap-2 flex-wrap">
              <span class="px-2 py-0.5 rounded bg-red-600 text-white text-[10px] font-black">${o.type}</span>
              <span class="text-xs font-extrabold text-red-800">${o.badge}</span>
              <span class="text-[10px] font-bold text-gray-600 bg-white px-2 py-0.5 rounded border border-red-100">${prodCount}</span>
            </div>
            <div class="text-sm font-extrabold text-gray-900 truncate mt-0.5">${o.title}</div>
            <div class="text-[11px] text-gray-500 truncate">${o.desc}</div>
          </div>
          <div class="flex items-center gap-1.5 shrink-0">
            <button type="button" data-edit-offer="${o.id}" class="px-2.5 py-1.5 rounded-lg bg-amber-100 hover:bg-amber-200 text-amber-900 text-xs font-extrabold">Edit / Products</button>
            <button type="button" data-del-offer="${o.id}" class="px-2.5 py-1.5 rounded-lg bg-red-100 hover:bg-red-200 text-red-800 text-xs font-extrabold">Delete</button>
          </div>
        </div>
      `;
      }).join('');
    }

    // --- RENDER BRANDS & CATEGORIES ---
    function renderBrands() {
      const container = document.getElementById('brand-pills');
      const allBrands = ['All', ...BRANDS];
      container.innerHTML = allBrands.map(b => {
        const active = selectedBrand === b;
        const fallbackSrc = BRAND_LOGOS[b] || BRAND_LOGOS['All'];
        const primarySrc = REAL_BRAND_LOGOS[b] || fallbackSrc;
        return `<button type="button" data-brand="${b}" class="brand-pill-btn p-2.5 rounded-xl border flex flex-col items-center justify-center gap-1.5 transition ${
          active
            ? 'theme-bg text-white border-transparent shadow-lg ring-2 ring-red-400 scale-[1.03]'
            : 'bg-white text-gray-800 border-red-200 hover:border-red-500 hover:bg-red-50'
        }">
          <div class="w-full h-12 rounded-lg bg-white border border-gray-100 flex items-center justify-center p-1 overflow-hidden">
            <img src="${primarySrc}" data-fb="${fallbackSrc}" onerror="if(this.dataset.fb && this.src!==this.dataset.fb){this.src=this.dataset.fb;}" alt="${b} original logo" width="180" height="44" class="h-10 w-auto max-w-full object-contain" />
          </div>
          <span class="text-[11px] font-extrabold tracking-tight">${b === 'All' ? 'All Brands' : b}</span>
        </button>`;
      }).join('');
    }

    function renderCategories() {
      const container = document.getElementById('category-pills');
      const allCats = ['All', ...CATEGORIES];
      container.innerHTML = allCats.map(c => {
        const active = selectedCategory === c;
        return `<button type="button" data-category="${c}" class="cat-pill-btn shrink-0 px-4 py-2 rounded-full text-xs sm:text-sm font-bold border transition ${
          active
            ? 'theme-bg text-white border-transparent shadow'
            : 'bg-white text-gray-700 border-red-200 hover:bg-red-50 hover:text-red-700'
        }">${c === 'All' ? 'All Categories' : c}</button>`;
      }).join('');
    }

    // --- RENDER PRODUCT CATALOG ---
    function getFinalPrice(p) {
      return Math.round(p.price * (1 - (p.discount || 0) / 100));
    }

    function renderCatalog() {
      const offerBar = document.getElementById('active-offer-bar');
      if (activeOfferFilter) {
        offerBar.classList.remove('hidden');
        document.getElementById('active-offer-label').textContent = `🎉 Showing Event Items for: "${activeOfferFilter.title}" (${activeOfferFilter.badge})`;
      } else {
        offerBar.classList.add('hidden');
      }

      let list = products.filter(p => {
        const matchBrand = selectedBrand === 'All' || p.brand === selectedBrand;
        const matchCat = selectedCategory === 'All' || p.category === selectedCategory;
        const matchOffer = !activeOfferFilter || (
          activeOfferFilter.productIds && activeOfferFilter.productIds.length > 0
            ? activeOfferFilter.productIds.includes(p.id)
            : (!activeOfferFilter.categories || activeOfferFilter.categories.length === 0 || activeOfferFilter.categories.includes(p.category))
        );
        const q = searchQuery.trim().toLowerCase();
        const matchQ = !q || p.name.toLowerCase().includes(q) || p.brand.toLowerCase().includes(q) || p.category.toLowerCase().includes(q);
        return matchBrand && matchCat && matchOffer && matchQ;
      });

      if (sortBy === 'price-asc') list.sort((a, b) => getFinalPrice(a) - getFinalPrice(b));
      else if (sortBy === 'price-desc') list.sort((a, b) => getFinalPrice(b) - getFinalPrice(a));
      else if (sortBy === 'discount-desc') list.sort((a, b) => (b.discount || 0) - (a.discount || 0));

      document.getElementById('catalog-count-label').textContent = `(${list.length} items)`;
      const grid = document.getElementById('product-grid');
      const empty = document.getElementById('empty-catalog');

      if (list.length === 0) {
        grid.innerHTML = '';
        empty.classList.remove('hidden');
        return;
      }
      empty.classList.add('hidden');

      grid.innerHTML = list.map(p => {
        const finalPrice = getFinalPrice(p);
        const savings = p.price - finalPrice;
        const ownerControls = activeMode === 'owner'
          ? `<div class="flex gap-2 mt-2 pt-2 border-t border-red-100">
               <button type="button" data-owner-edit="${p.id}" class="flex-1 py-1.5 rounded-lg bg-amber-100 hover:bg-amber-200 text-amber-900 text-xs font-extrabold">Edit</button>
               <button type="button" data-owner-del="${p.id}" class="flex-1 py-1.5 rounded-lg bg-red-100 hover:bg-red-200 text-red-800 text-xs font-extrabold">Delete</button>
             </div>`
          : '';

        return `
          <article class="theme-card product-card border border-red-100 overflow-hidden flex flex-col shadow-sm">
            <div class="relative h-52 bg-red-50/40 overflow-hidden">
              <img src="${p.image}" alt="${p.name}" class="w-full h-full object-cover" />
              ${p.discount > 0 ? `<span class="absolute top-3 left-3 px-2.5 py-1 rounded-full theme-bg text-white text-xs font-black shadow">${p.discount}% OFF</span>` : ''}
              <span class="absolute top-3 right-3 px-2.5 py-1 rounded-full bg-white/95 text-red-700 text-[11px] font-extrabold shadow">${p.brand}</span>
            </div>
            <div class="p-4 flex-1 flex flex-col justify-between gap-3">
              <div>
                <span class="text-[11px] font-bold uppercase tracking-wider theme-text">${p.category}</span>
                <h3 class="product-title text-base font-extrabold text-gray-900 mt-0.5 leading-snug">${p.name}</h3>
                <p class="text-xs text-gray-500 mt-1 line-clamp-2">${p.desc || ''}</p>
              </div>
              <div>
                <div class="flex items-baseline gap-2 mb-3">
                  <span class="product-price text-xl font-black theme-text">₹${finalPrice.toLocaleString('en-IN')}</span>
                  ${p.discount > 0 ? `<span class="text-xs text-gray-400 line-through">₹${p.price.toLocaleString('en-IN')}</span>` : ''}
                  ${savings > 0 ? `<span class="text-[11px] font-bold text-green-700 ml-auto">Save ₹${savings.toLocaleString('en-IN')}</span>` : ''}
                </div>
                <button type="button" data-add-cart="${p.id}" class="w-full py-2.5 theme-btn font-extrabold text-sm flex items-center justify-center gap-2">
                  <span>🛒</span> Add to Cart
                </button>
                ${ownerControls}
              </div>
            </div>
          </article>
        `;
      }).join('');
    }

    // --- CART ---
    function renderCart() {
      const totalItems = cart.reduce((s, item) => s + item.qty, 0);
      document.getElementById('cart-count-badge').textContent = totalItems;

      const container = document.getElementById('cart-items-container');
      if (cart.length === 0) {
        container.innerHTML = `<div class="text-center py-16 text-gray-500">
          <div class="text-4xl mb-2">🛍️</div>
          <p class="font-bold text-gray-700">Your cart is empty</p>
          <p class="text-xs mt-1">Add bags or accessories to get started.</p>
        </div>`;
        document.getElementById('cart-total').textContent = '₹0';
        document.getElementById('cart-savings').textContent = '₹0';
        return;
      }

      let totalPayable = 0;
      let totalSavings = 0;

      container.innerHTML = cart.map(item => {
        const prod = products.find(p => p.id === item.id);
        if (!prod) return '';
        const unitFinal = getFinalPrice(prod);
        const unitSave = prod.price - unitFinal;
        totalPayable += unitFinal * item.qty;
        totalSavings += unitSave * item.qty;
        return `
          <div class="flex gap-3 p-3 rounded-xl border border-red-100 bg-white shadow-sm items-center">
            <img src="${prod.image}" alt="${prod.name}" class="w-16 h-16 rounded-lg object-cover bg-red-50 shrink-0" />
            <div class="flex-1 min-w-0">
              <h4 class="text-xs font-extrabold text-gray-900 truncate">${prod.name}</h4>
              <p class="text-[11px] text-gray-500">${prod.brand} &bull; ₹${unitFinal.toLocaleString('en-IN')}</p>
              <div class="flex items-center gap-2 mt-1.5">
                <button type="button" data-cart-dec="${prod.id}" class="w-6 h-6 rounded bg-red-100 text-red-700 font-black text-xs hover:bg-red-200">-</button>
                <span class="text-xs font-bold w-5 text-center">${item.qty}</span>
                <button type="button" data-cart-inc="${prod.id}" class="w-6 h-6 rounded bg-red-100 text-red-700 font-black text-xs hover:bg-red-200">+</button>
                <button type="button" data-cart-rem="${prod.id}" class="ml-auto text-[11px] font-bold text-red-600 hover:underline">Remove</button>
              </div>
            </div>
          </div>
        `;
      }).join('');

      document.getElementById('cart-total').textContent = '₹' + totalPayable.toLocaleString('en-IN');
      document.getElementById('cart-savings').textContent = '₹' + totalSavings.toLocaleString('en-IN');
    }

    function addToCart(id) {
      const existing = cart.find(c => c.id === id);
      if (existing) existing.qty += 1;
      else cart.push({ id, qty: 1 });
      saveCart();
      renderCart();
      const prod = products.find(p => p.id === id);
      showToast(`Added "${prod ? prod.name : 'Item'}" to cart`);
    }

    // --- OWNER INVENTORY ---
    function populateOwnerSelects() {
      document.getElementById('owner-prod-brand').innerHTML = BRANDS.map(b => `<option value="${b}">${b}</option>`).join('');
      document.getElementById('owner-prod-category').innerHTML = CATEGORIES.map(c => `<option value="${c}">${c}</option>`).join('');
      const offerCatEl = document.getElementById('offer-target-cat');
      if (offerCatEl) {
        offerCatEl.innerHTML = '<option value="ALL">All Categories</option>' + CATEGORIES.map(c => `<option value="${c}">${c}</option>`).join('');
      }
      renderOfferProductPicker();
    }

    function renderOwnerInventory() {
      const q = (document.getElementById('owner-inv-search').value || '').trim().toLowerCase();
      const filtered = products.filter(p => !q || p.name.toLowerCase().includes(q) || p.brand.toLowerCase().includes(q));
      document.getElementById('owner-inv-count').textContent = products.length;
      document.getElementById('owner-inv-list').innerHTML = filtered.map(p => `
        <div class="flex items-center gap-3 p-2.5 rounded-xl hover:bg-red-50 transition">
          <img src="${p.image}" alt="${p.name}" class="w-12 h-12 rounded-lg object-cover border border-red-100 shrink-0" />
          <div class="flex-1 min-w-0">
            <div class="text-xs font-extrabold text-gray-900 truncate">${p.name}</div>
            <div class="text-[11px] text-gray-500">${p.brand} &bull; ${p.category} &bull; ₹${getFinalPrice(p)} (${p.discount}% off)</div>
          </div>
          <button type="button" data-owner-edit="${p.id}" class="px-2.5 py-1 rounded-md bg-amber-100 hover:bg-amber-200 text-amber-900 text-xs font-bold">Edit</button>
          <button type="button" data-owner-del="${p.id}" class="px-2.5 py-1 rounded-md bg-red-100 hover:bg-red-200 text-red-800 text-xs font-bold">Delete</button>
        </div>
      `).join('');
    }

    function startEditProduct(id) {
      const p = products.find(x => x.id === id);
      if (!p) return;
      document.getElementById('owner-panel').classList.remove('hidden');
      document.getElementById('owner-edit-id').value = p.id;
      document.getElementById('owner-form-title').textContent = 'Edit Product';
      document.getElementById('owner-save-btn').textContent = 'Save Product Changes';
      document.getElementById('owner-reset-form-btn').classList.remove('hidden');
      document.getElementById('owner-prod-name').value = p.name;
      document.getElementById('owner-prod-brand').value = BRANDS.includes(p.brand) ? p.brand : BRANDS[0];
      document.getElementById('owner-prod-category').value = CATEGORIES.includes(p.category) ? p.category : CATEGORIES[0];
      document.getElementById('owner-prod-price').value = p.price;
      document.getElementById('owner-prod-discount').value = p.discount;
      document.getElementById('owner-prod-desc').value = p.desc || '';
      uploadedOwnerImage = p.image;
      document.getElementById('owner-img-preview').src = p.image;
      document.getElementById('owner-prod-img-url').value = p.image.startsWith('http') ? p.image : '';
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function resetOwnerForm() {
      document.getElementById('owner-product-form').reset();
      document.getElementById('owner-edit-id').value = '';
      document.getElementById('owner-form-title').textContent = 'Add New Product';
      document.getElementById('owner-save-btn').textContent = '+ Add Product to Store';
      document.getElementById('owner-reset-form-btn').classList.add('hidden');
      uploadedOwnerImage = '';
      document.getElementById('owner-img-preview').src = IMG_SUITCASE;
    }

    function deleteProduct(id) {
      products = products.filter(p => p.id !== id);
      cart = cart.filter(c => c.id !== id);
      saveProducts();
      saveCart();
      renderCatalog();
      renderOwnerInventory();
      renderOfferProductPicker();
      renderCart();
      showToast('Product deleted immediately');
    }

    // --- MODE SWITCHING ---
    function setMode(mode) {
      activeMode = mode;
      const banner = document.getElementById('mode-banner');
      const ownerPanel = document.getElementById('owner-panel');
      const devPanel = document.getElementById('developer-panel');
      const badge = document.getElementById('mode-banner-badge');
      const text = document.getElementById('mode-banner-text');

      ownerPanel.classList.add('hidden');
      devPanel.classList.add('hidden');

      if (mode === 'user') {
        banner.classList.add('hidden');
      } else if (mode === 'owner') {
        banner.classList.remove('hidden');
        ownerPanel.classList.remove('hidden');
        badge.textContent = 'OWNER MODE';
        text.textContent = 'Manage products, prices, discounts & images live.';
        renderOwnerInventory();
        renderOwnerOffers();
      } else if (mode === 'developer') {
        banner.classList.remove('hidden');
        devPanel.classList.remove('hidden');
        badge.textContent = 'DEVELOPER MODE';
        text.textContent = 'Modify styles, fonts, logo, contact info & access codes live.';
      }
      renderCatalog();
    }

    // --- INIT & EVENT LISTENERS ---
    window.addEventListener('DOMContentLoaded', () => {
      loadState();
      populateOwnerSelects();
      applyConfigToDOM();
      renderFestiveOffers();
      renderBrands();
      renderCategories();
      renderCatalog();
      renderCart();

      // Splash auto-hide
      const splash = document.getElementById('entry-splash');
      let splashTimer = setTimeout(() => splash.classList.add('splash-hidden'), 2600);
      document.getElementById('skip-splash-btn').addEventListener('click', () => {
        clearTimeout(splashTimer);
        splash.classList.add('splash-hidden');
      });

      // Brand & Category delegation
      document.getElementById('brand-pills').addEventListener('click', (e) => {
        const btn = e.target.closest('[data-brand]');
        if (!btn) return;
        selectedBrand = btn.dataset.brand;
        renderBrands();
        renderCatalog();
        document.getElementById('catalog').scrollIntoView({ behavior: 'smooth' });
      });

      document.getElementById('category-pills').addEventListener('click', (e) => {
        const btn = e.target.closest('[data-category]');
        if (!btn) return;
        selectedCategory = btn.dataset.category;
        renderCategories();
        renderCatalog();
      });

      document.getElementById('clear-filters-btn').addEventListener('click', () => {
        activeOfferFilter = null;
        selectedBrand = 'All';
        selectedCategory = 'All';
        searchQuery = '';
        document.getElementById('search-input').value = '';
        document.getElementById('mobile-search-input').value = '';
        renderBrands();
        renderCategories();
        renderCatalog();
      });

      document.getElementById('empty-reset-btn').addEventListener('click', () => {
        document.getElementById('clear-filters-btn').click();
      });

      // Search & Sort
      const handleSearch = (val) => {
        searchQuery = val;
        renderCatalog();
      };
      document.getElementById('search-input').addEventListener('input', (e) => handleSearch(e.target.value));
      document.getElementById('mobile-search-input').addEventListener('input', (e) => handleSearch(e.target.value));
      document.getElementById('sort-select').addEventListener('change', (e) => {
        sortBy = e.target.value;
        renderCatalog();
      });

      // Product Grid Actions (Add to Cart, Owner Edit/Delete)
      document.getElementById('product-grid').addEventListener('click', (e) => {
        const addBtn = e.target.closest('[data-add-cart]');
        if (addBtn) { addToCart(addBtn.dataset.addCart); return; }
        const editBtn = e.target.closest('[data-owner-edit]');
        if (editBtn) { startEditProduct(editBtn.dataset.ownerEdit); return; }
        const delBtn = e.target.closest('[data-owner-del]');
        if (delBtn) { deleteProduct(delBtn.dataset.ownerDel); return; }
      });

      // Cart Drawer
      const cartBackdrop = document.getElementById('cart-drawer-backdrop');
      document.getElementById('open-cart-btn').addEventListener('click', () => cartBackdrop.classList.remove('hidden'));
      document.getElementById('close-cart-btn').addEventListener('click', () => cartBackdrop.classList.add('hidden'));
      cartBackdrop.addEventListener('click', (e) => {
        if (e.target === cartBackdrop) cartBackdrop.classList.add('hidden');
      });

      document.getElementById('cart-items-container').addEventListener('click', (e) => {
        const inc = e.target.closest('[data-cart-inc]');
        const dec = e.target.closest('[data-cart-dec]');
        const rem = e.target.closest('[data-cart-rem]');
        if (inc) {
          const item = cart.find(c => c.id === inc.dataset.cartInc);
          if (item) item.qty += 1;
        } else if (dec) {
          const item = cart.find(c => c.id === dec.dataset.cartDec);
          if (item) {
            item.qty -= 1;
            if (item.qty <= 0) cart = cart.filter(c => c.id !== item.id);
          }
        } else if (rem) {
          cart = cart.filter(c => c.id !== rem.dataset.cartRem);
        } else return;
        saveCart();
        renderCart();
      });

      document.getElementById('clear-cart-btn').addEventListener('click', () => {
        cart = [];
        saveCart();
        renderCart();
        showToast('Cart cleared');
      });

      document.getElementById('checkout-btn').addEventListener('click', () => {
        if (cart.length === 0) { showToast('Your cart is empty!'); return; }
        const lines = cart.map(c => {
          const p = products.find(x => x.id === c.id);
          return p ? `${c.qty}x ${p.name} (₹${getFinalPrice(p)})` : '';
        }).filter(Boolean).join('%0A');
        const cleanPhone = config.phone.replace(/[^\d]/g, '');
        window.open(`https://wa.me/${cleanPhone}?text=Hello%20${encodeURIComponent(config.shopName)},%20I%20would%20like%20to%20order:%0A${lines}`, '_blank', 'noopener,noreferrer');
      });

      // Owners Tab Modal
      const codeModal = document.getElementById('code-modal');
      const codeInput = document.getElementById('access-code-input');
      const codeError = document.getElementById('code-error-msg');

      document.getElementById('owners-tab-btn').addEventListener('click', () => {
        codeError.classList.add('hidden');
        codeInput.value = '';
        codeModal.classList.remove('hidden');
        setTimeout(() => codeInput.focus(), 50);
      });
      document.getElementById('close-code-modal-btn').addEventListener('click', () => codeModal.classList.add('hidden'));
      document.getElementById('cancel-code-btn').addEventListener('click', () => codeModal.classList.add('hidden'));

      document.getElementById('code-access-form').addEventListener('submit', (e) => {
        e.preventDefault();
        const entered = codeInput.value.trim();
        if (entered === config.ownerCode) {
          codeModal.classList.add('hidden');
          setMode('owner');
          showToast('Owner Mode Activated!');
        } else if (entered === config.devCode) {
          codeModal.classList.add('hidden');
          setMode('developer');
          showToast('Developer Mode Activated!');
        } else {
          codeError.textContent = 'Invalid access code. Please try again.';
          codeError.classList.remove('hidden');
        }
      });

      // Mode Banner controls
      document.getElementById('exit-mode-btn').addEventListener('click', () => {
        setMode('user');
        showToast('Returned to User Mode');
      });
      document.getElementById('toggle-panel-btn').addEventListener('click', () => {
        if (activeMode === 'owner') document.getElementById('owner-panel').classList.toggle('hidden');
        if (activeMode === 'developer') document.getElementById('developer-panel').classList.toggle('hidden');
      });
      document.getElementById('close-owner-panel-btn').addEventListener('click', () => document.getElementById('owner-panel').classList.add('hidden'));
      document.getElementById('close-dev-panel-btn').addEventListener('click', () => document.getElementById('developer-panel').classList.add('hidden'));

      // Owner Form & Inventory
      document.getElementById('owner-prod-file').addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (ev) => {
          uploadedOwnerImage = ev.target.result;
          document.getElementById('owner-img-preview').src = uploadedOwnerImage;
        };
        reader.readAsDataURL(file);
      });
      document.getElementById('owner-prod-img-url').addEventListener('input', (e) => {
        if (e.target.value.trim()) {
          uploadedOwnerImage = e.target.value.trim();
          document.getElementById('owner-img-preview').src = uploadedOwnerImage;
        }
      });
      document.getElementById('owner-reset-form-btn').addEventListener('click', resetOwnerForm);
      document.getElementById('owner-inv-search').addEventListener('input', renderOwnerInventory);
      document.getElementById('owner-inv-list').addEventListener('click', (e) => {
        const editBtn = e.target.closest('[data-owner-edit]');
        if (editBtn) startEditProduct(editBtn.dataset.ownerEdit);
        const delBtn = e.target.closest('[data-owner-del]');
        if (delBtn) deleteProduct(delBtn.dataset.ownerDel);
      });

      document.getElementById('offer-img-file').addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (ev) => { uploadedOfferImage = ev.target.result; };
        reader.readAsDataURL(file);
      });

      function resetOfferForm() {
        document.getElementById('owner-offer-form').reset();
        document.getElementById('offer-edit-id').value = '';
        document.getElementById('owner-offer-form-title').textContent = '🎉 Advertise Festive Offer / Event';
        document.getElementById('owner-offer-submit-btn').textContent = '+ Publish Offer / Event Live';
        document.getElementById('owner-offer-cancel-btn').classList.add('hidden');
        uploadedOfferImage = '';
        renderOfferProductPicker([]);
      }

      document.getElementById('owner-offer-cancel-btn').addEventListener('click', resetOfferForm);

      document.getElementById('owner-offer-form').addEventListener('submit', (e) => {
        e.preventDefault();
        const editId = document.getElementById('offer-edit-id').value;
        const title = document.getElementById('offer-title').value.trim();
        const type = document.getElementById('offer-type').value;
        const badge = document.getElementById('offer-badge').value.trim();
        const targetCat = document.getElementById('offer-target-cat').value;
        const date = document.getElementById('offer-date').value.trim() || 'Active Now';
        const desc = document.getElementById('offer-desc').value.trim();
        const categories = targetCat === 'ALL' ? [] : [targetCat];
        const productIds = Array.from(document.querySelectorAll('.offer-prod-checkbox:checked')).map(cb => cb.value);

        if (editId) {
          const idx = offers.findIndex(o => o.id === editId);
          if (idx !== -1) {
            const img = uploadedOfferImage || offers[idx].image || '';
            offers[idx] = { ...offers[idx], title, type, badge, date, targetCategory: targetCat, categories, productIds, desc, image: img };
            showToast('Offer / event & products updated live!');
          }
        } else {
          offers.unshift({ id: 'off_' + Date.now(), title, type, badge, date, targetCategory: targetCat, categories, productIds, desc, image: uploadedOfferImage });
          currentOfferIndex = 0;
          showToast('Festive offer / event published live!');
        }
        saveOffers();
        resetOfferForm();
        renderFestiveOffers();
        renderOwnerOffers();
      });

      // Offer Carousel Controls (Arrows, Dots, Touch Swipe, Click to View Event Items)
      document.getElementById('offer-prev-btn').addEventListener('click', () => {
        currentOfferIndex -= 1;
        updateOfferSlidePosition();
      });
      document.getElementById('offer-next-btn').addEventListener('click', () => {
        currentOfferIndex += 1;
        updateOfferSlidePosition();
      });
      document.getElementById('offer-dots').addEventListener('click', (e) => {
        const dot = e.target.closest('[data-offer-dot]');
        if (!dot) return;
        currentOfferIndex = Number(dot.dataset.offerDot);
        updateOfferSlidePosition();
      });

      const carouselTrack = document.getElementById('offer-carousel-track');
      let touchStartX = 0;
      carouselTrack.addEventListener('touchstart', (e) => {
        touchStartX = e.changedTouches[0].screenX;
      }, { passive: true });
      carouselTrack.addEventListener('touchend', (e) => {
        const dx = e.changedTouches[0].screenX - touchStartX;
        if (Math.abs(dx) > 40) {
          currentOfferIndex += dx < 0 ? 1 : -1;
          updateOfferSlidePosition();
        }
      }, { passive: true });

      carouselTrack.addEventListener('click', (e) => {
        const card = e.target.closest('[data-offer-click]');
        if (!card) return;
        const off = offers.find(x => x.id === card.dataset.offerClick);
        if (!off) return;
        activeOfferFilter = off;
        selectedBrand = 'All';
        selectedCategory = 'All';
        renderBrands();
        renderCategories();
        renderCatalog();
        document.getElementById('catalog').scrollIntoView({ behavior: 'smooth' });
        showToast(`Showing items for "${off.title}"`);
      });

      document.getElementById('clear-offer-filter-btn').addEventListener('click', () => {
        activeOfferFilter = null;
        renderCatalog();
      });

      document.getElementById('owner-offers-list').addEventListener('click', (e) => {
        const editBtn = e.target.closest('[data-edit-offer]');
        if (editBtn) {
          const o = offers.find(x => x.id === editBtn.dataset.editOffer);
          if (!o) return;
          document.getElementById('offer-edit-id').value = o.id;
          document.getElementById('owner-offer-form-title').textContent = 'Edit Event / Add Products';
          document.getElementById('owner-offer-submit-btn').textContent = 'Save Event & Products';
          document.getElementById('owner-offer-cancel-btn').classList.remove('hidden');
          document.getElementById('offer-title').value = o.title;
          document.getElementById('offer-type').value = o.type;
          document.getElementById('offer-badge').value = o.badge;
          document.getElementById('offer-date').value = o.date || '';
          document.getElementById('offer-desc').value = o.desc || '';
          document.getElementById('offer-target-cat').value = (o.categories && o.categories.length === 1) ? o.categories[0] : 'ALL';
          renderOfferProductPicker(o.productIds || []);
          return;
        }
        const delBtn = e.target.closest('[data-del-offer]');
        if (!delBtn) return;
        offers = offers.filter(o => o.id !== delBtn.dataset.delOffer);
        saveOffers();
        renderFestiveOffers();
        renderOwnerOffers();
        showToast('Offer / event removed');
      });

      document.getElementById('owner-product-form').addEventListener('submit', (e) => {
        e.preventDefault();
        const editId = document.getElementById('owner-edit-id').value;
        const name = document.getElementById('owner-prod-name').value.trim();
        const brand = document.getElementById('owner-prod-brand').value;
        const category = document.getElementById('owner-prod-category').value;
        const price = Number(document.getElementById('owner-prod-price').value);
        const discount = Number(document.getElementById('owner-prod-discount').value) || 0;
        const desc = document.getElementById('owner-prod-desc').value.trim();
        const image = uploadedOwnerImage || IMG_SUITCASE;

        if (editId) {
          const idx = products.findIndex(p => p.id === editId);
          if (idx !== -1) {
            products[idx] = { ...products[idx], name, brand, category, price, discount, desc, image };
            showToast('Product updated live for all users!');
          }
        } else {
          products.unshift({ id: 'p_' + Date.now(), name, brand, category, price, discount, desc, image });
          showToast('New product added live!');
        }
        saveProducts();
        resetOwnerForm();
        renderOwnerInventory();
        renderOfferProductPicker();
        renderCatalog();
      });

      // Developer Mode Live Controls
      document.getElementById('dev-primary-color').addEventListener('input', (e) => {
        config.primaryColor = e.target.value;
        config.darkColor = e.target.value;
        saveConfig();
        applyConfigToDOM();
      });
      document.getElementById('dev-bright-color').addEventListener('input', (e) => {
        config.brightColor = e.target.value;
        saveConfig();
        applyConfigToDOM();
      });

      const PRESETS = {
        'bright-red': { primaryColor: '#dc2626', brightColor: '#ef4444', darkColor: '#991b1b' },
        'crimson': { primaryColor: '#e11d48', brightColor: '#f43f5e', darkColor: '#9f1239' },
        'scarlet': { primaryColor: '#b91c1c', brightColor: '#dc2626', darkColor: '#7f1d1d' },
        'royal': { primaryColor: '#2563eb', brightColor: '#3b82f6', darkColor: '#1e3a8a' },
        'emerald': { primaryColor: '#059669', brightColor: '#10b981', darkColor: '#064e3b' }
      };
      document.querySelectorAll('.dev-preset-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const p = PRESETS[btn.dataset.preset];
          if (!p) return;
          Object.assign(config, p);
          saveConfig();
          applyConfigToDOM();
          showToast('Theme updated immediately!');
        });
      });

      document.getElementById('dev-font-select').addEventListener('change', (e) => {
        config.fontFamily = e.target.value;
        saveConfig();
        applyConfigToDOM();
      });
      document.getElementById('dev-logo-size-range').addEventListener('input', (e) => {
        config.logoSize = Number(e.target.value);
        saveConfig();
        applyConfigToDOM();
      });
      document.getElementById('dev-radius-range').addEventListener('input', (e) => {
        config.radius = Number(e.target.value);
        saveConfig();
        applyConfigToDOM();
      });
      document.getElementById('dev-shop-name').addEventListener('input', (e) => {
        config.shopName = e.target.value || 'SRINIVASA BAGS';
        saveConfig();
        applyConfigToDOM();
      });
      document.getElementById('dev-hero-title').addEventListener('input', (e) => {
        config.heroTitle = e.target.value;
        saveConfig();
        applyConfigToDOM();
      });


      document.getElementById('dev-email').addEventListener('input', (e) => {
        config.email = e.target.value;
        saveConfig();
        applyConfigToDOM();
      });

      document.getElementById('dev-add-phone-btn').addEventListener('click', () => {
        const val = document.getElementById('dev-new-phone').value.trim();
        if (!val) return;
        config.phones = [...(config.phones || []), val];
        document.getElementById('dev-new-phone').value = '';
        saveConfig();
        applyConfigToDOM();
        showToast('Phone number added!');
      });
      document.getElementById('dev-phones-list').addEventListener('click', (e) => {
        const btn = e.target.closest('[data-del-phone]');
        if (!btn) return;
        config.phones.splice(Number(btn.dataset.delPhone), 1);
        saveConfig();
        applyConfigToDOM();
      });

      document.getElementById('dev-add-wa-btn').addEventListener('click', () => {
        const val = document.getElementById('dev-new-wa').value.trim();
        if (!val) return;
        config.whatsapps = [...(config.whatsapps || []), val];
        document.getElementById('dev-new-wa').value = '';
        saveConfig();
        applyConfigToDOM();
        showToast('WhatsApp number added!');
      });
      document.getElementById('dev-wa-list').addEventListener('click', (e) => {
        const btn = e.target.closest('[data-del-wa]');
        if (!btn) return;
        config.whatsapps.splice(Number(btn.dataset.delWa), 1);
        saveConfig();
        applyConfigToDOM();
      });

      document.getElementById('dev-add-social-btn').addEventListener('click', () => {
        const name = document.getElementById('dev-new-social-name').value.trim();
        const url = document.getElementById('dev-new-social-url').value.trim();
        if (!name || !url) { showToast('Enter platform name and URL'); return; }
        config.socials = [...(config.socials || []), { name, icon: '🔗', url }];
        document.getElementById('dev-new-social-name').value = '';
        document.getElementById('dev-new-social-url').value = '';
        saveConfig();
        applyConfigToDOM();
        showToast(`${name} link added!`);
      });
      document.getElementById('dev-socials-list').addEventListener('click', (e) => {
        const btn = e.target.closest('[data-del-social]');
        if (!btn) return;
        config.socials.splice(Number(btn.dataset.delSocial), 1);
        saveConfig();
        applyConfigToDOM();
      });

      // Per-Element Styler
      document.getElementById('dev-el-size').addEventListener('input', (e) => {
        document.getElementById('dev-el-size-val').textContent = e.target.value + 'px';
      });
      document.getElementById('dev-apply-el-btn').addEventListener('click', () => {
        const sel = document.getElementById('dev-el-target').value;
        config.elementStyles = config.elementStyles || {};
        config.elementStyles[sel] = {
          fontSize: Number(document.getElementById('dev-el-size').value),
          color: document.getElementById('dev-el-color').value,
          bg: document.getElementById('dev-el-bg').value,
          fontFamily: document.getElementById('dev-el-font').value
        };
        saveConfig();
        applyConfigToDOM();
        showToast('Element style updated immediately!');
      });
      document.getElementById('dev-clear-el-btn').addEventListener('click', () => {
        const sel = document.getElementById('dev-el-target').value;
        if (config.elementStyles) delete config.elementStyles[sel];
        saveConfig();
        applyConfigToDOM();
        showToast('Element style reset');
      });
      document.getElementById('dev-address').addEventListener('input', (e) => {
        config.address = e.target.value;
        saveConfig();
        applyConfigToDOM();
      });
      document.getElementById('dev-logo-file').addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (ev) => {
          config.logoDataUrl = ev.target.result;
          saveConfig();
          applyConfigToDOM();
          showToast('Logo updated immediately!');
        };
        reader.readAsDataURL(file);
      });

      document.getElementById('dev-save-codes-btn').addEventListener('click', () => {
        const oc = document.getElementById('dev-owner-code').value.trim();
        const dc = document.getElementById('dev-dev-code').value.trim();
        if (oc) config.ownerCode = oc;
        if (dc) config.devCode = dc;
        saveConfig();
        showToast('Access codes updated!');
      });

      document.getElementById('dev-reset-codes-btn').addEventListener('click', () => {
        config.ownerCode = DEFAULT_CONFIG.ownerCode;
        config.devCode = DEFAULT_CONFIG.devCode;
        saveConfig();
        applyConfigToDOM();
        showToast('Codes reset to 216216216 & dev216');
      });

      document.getElementById('dev-apply-css-btn').addEventListener('click', () => {
        config.customCss = document.getElementById('dev-css-input').value;
        saveConfig();
        applyConfigToDOM();
        showToast('Custom CSS applied!');
      });

      document.getElementById('dev-replay-splash-btn').addEventListener('click', () => {
        splash.classList.remove('splash-hidden');
        setTimeout(() => splash.classList.add('splash-hidden'), 2600);
      });

      document.getElementById('dev-factory-reset-btn').addEventListener('click', () => {
        config = { ...DEFAULT_CONFIG };
        products = [...DEFAULT_PRODUCTS];
        saveConfig();
        saveProducts();
        applyConfigToDOM();
        renderBrands();
        renderCategories();
        renderCatalog();
        showToast('Website reset to factory defaults!');
      });
    });